#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Done%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

# copy_clip TEXT puts TEXT (with newlines) on the Windows clipboard via
# clip.exe (Git Bash / WSL interop falls back to wl-copy / pbcopy).
copy_clip() {
  local text="$1"
  if { command -v clip.exe >/dev/null 2>&1 && printf '%s' "$text" | clip.exe; } || \
     { command -v pbcopy  >/dev/null 2>&1 && printf '%s' "$text" | pbcopy; } || \
     { command -v wl-copy >/dev/null 2>&1 && printf '%s' "$text" | wl-copy; }; then
    printf '  %s✓ copied to clipboard%s — click the field, Ctrl+V to paste it\n' "$GREEN" "$RESET"
  else
    warn "no clipboard tool found — type this inside the marked fence into the field:"
    printf '  %s┌── copy exactly below ──%s\n' "$DIM" "$RESET"
    printf '%s\n' "$text" | sed 's/^/  │ /'
    printf '  %s└── copy exactly above ──%s\n' "$DIM" "$RESET"
  fi
}

# show_text TEXT prints the text in a visible fence so it can be checked.
show_text() {
  printf '  %s┌── text ──%s\n' "$DIM" "$RESET"
  printf '%s\n' "$1" | sed 's/^/  │ /'
  printf '  %s└──────────%s\n' "$DIM" "$RESET"
}

# generic per-template flow: SUBJECT MSG1 MSG2?
do_template() {
  local subject="$1" message="$2"
  step "Pencil (✏ EDIT) on this template, if its fields are editable."
  say "  - Sender name (where editable): Hacienda de LuisAna"
  say "  - Reply to (where editable):    haciendadeluisiana@gmail.com"
  say "  - From / action URL / SMTP: leave unchanged."
  pause ""
  step "Subject — where editable, paste:"
  show_text "$subject"
  copy_clip "$subject"
  pause ""
  step "Message — paste ONLY if the Message field is editable:"
  show_text "$message"
  copy_clip "$message"
  warn "If a field is read-only or Firebase refuses the edit, leave the existing value in place — never remove its security instructions or the %LINK%."
  if confirm "Saved this template? (Enter/n if still working)"; then :; fi
}

TOTAL_STAGES=8

# (message bodies defined once, below, before the first do_template call.)

banner "Firebase Auth templates — Hacienda de LuisAna"

CONSOLE_URL="https://console.firebase.google.com/project/hacienda-de-luisana/authentication/emails"

# ── Stage 1: open the templates page ─────────────────────────────────────
stage "Open Authentication → Templates"
open_url "$CONSOLE_URL"
step "Sign in with a Google account that owns the hacienda-de-luisana project, if asked."
step "You should be on Authentication → Templates: a list of email/SMS templates."
warn "You must be signed in with the SAME Google account that opened your browser to this Firebase project."
if confirm "Is the Templates list showing (Password reset, Email address verification, ...)"; then :; fi

# ── Stage 2: Email address verification ─────────────────────────────────
stage "Email address verification"
say "Open the template list's 'Email address verification' item, then edit."
do_template \
  "Verify your email for Hacienda de LuisAna" \
  "Hello,

Thank you for joining Hacienda de LuisAna. Please verify your email address by
following this link:

%LINK%

If you did not request this verification, you can ignore this email.

Thank you,
Hacienda de LuisAna"

# ── Stage 3: Password reset ──────────────────────────────────────────────
stage "Password reset"
say "This is the one body Firebase's help docs say is normally editable."
do_template \
  "Reset your Hacienda de LuisAna password" \
  "Hello,

We received a request to reset the password for your Hacienda de LuisAna account.
To choose a new password, follow this link:

%LINK%

If you did not request a password reset, you can ignore this email. Your
password will not change unless the reset is completed.

Need help? Contact us at haciendadeluisiana@gmail.com.

Thank you,
Hacienda de LuisAna"

# ── Stage 4: Email address change ────────────────────────────────────────
stage "Email address change"
say "This notice goes to the OLD address — it is the undo link, not an approve link."
do_template \
  "Your Hacienda de LuisAna sign-in email was changed" \
  "Hello,

The sign-in email for your Hacienda de LuisAna account was changed to
%NEW_EMAIL%.

If you did not make this change, follow the link below to restore your previous
email address. Afterward, reset your password and contact us at
haciendadeluisiana@gmail.com.

%LINK%

Thank you,
Hacienda de LuisAna"

# ── Stage 5: Multi-factor enrollment notification ────────────────────────
stage "Multi-factor enrollment notification"
say "Note: editing this template does NOT turn multi-factor auth on."
do_template \
  "A sign-in verification method was added to your Hacienda de LuisAna account" \
  "Hello,

A new two-step verification method was added to your Hacienda de LuisAna account.

If you did not add it, follow the link below to remove the new method.
Afterward, reset your password and contact us at haciendadeluisiana@gmail.com.

%LINK%

Thank you,
Hacienda de LuisAna"

# ── Stage 6: SMS verification ────────────────────────────────────────────
stage "SMS verification"
step "Open the SMS verification template."
warn "Leave the Firebase-provided SMS text and its code placeholder intact if the console does not allow editing — editing a template does not enable phone sign-in or MFA."
pause ""
if confirm "SMS template left intact (or, if editable, kept the code placeholder)"; then :; fi

# ── Stage 7: Public-facing name ──────────────────────────────────────────
stage "Check the project's public-facing name"
open_url "https://console.firebase.google.com/project/hacienda-de-luisana/settings/general"
step "Scroll to Your project → Public-facing name; it should read: Hacienda de LuisAna"
step "If you used %APP_NAME% in any subject or message, this name is what Firebase substitutes for it."
if confirm "Public-facing name is 'Hacienda de LuisAna'"; then :; fi

# ── Stage 8: post-save test checklist ────────────────────────────────────
stage "Post-save tests (on a real device, with a real inbox)"
warn "These need the deployed website plus a test inbox you control — they cannot be verified from this terminal."
step "1. On the deployed Guest site, request a password reset from the sign-in screen (use a test Guest account you own); check inbox AND spam."
step "2. Confirm sender name, subject and message; open the link and finish the reset. Never share an action link with anyone."
step "3. Register a NEW test Guest with an inbox you control; open the verification link from that email, then on the site choose 'I have verified my email' to refresh the token."
step "4. If the request fails, the account still exists — retry from My Bookings / My Profile 'Send verification email'; do NOT register again. Google and browser-demo accounts skip this flow; verification is informational and does not block Guest access."
warn "Saving console templates and pushing repo changes is not a deployment — an Auth-emulator test proves real delivery nothing."
pause ""
finish
